export async function post(t,e=null,r=[]){try{const o=e!==null&&!(e instanceof FormData)&&!(e instanceof URLSearchParams);const n={"X-Requested-With":"XMLHttpRequest"};if(o){n["Content-Type"]="application/json"}const c={method:"POST",headers:n};if(e!==null){c.body=o?JSON.stringify(e):e}const s=await fetch(`${CFG_GLPI.root_doc}/${t}`,c);if(!s.ok&&!r.includes(s.status)){throw new Error("POST request failed")}return s}catch(t){glpi_toast_error(__("An unexpected error occurred."));throw t}}export async function get(t,{quiet:e=false}={}){try{const e={method:"GET",headers:{"X-Requested-With":"XMLHttpRequest"}};const r=await fetch(`${CFG_GLPI.root_doc}/${t}`,e);if(!r.ok){throw new Error("GET request failed")}return r}catch(t){if(!e){glpi_toast_error(__("An unexpected error occurred."))}throw t}}